import os
import boto3

def welcome_translate(text, target_language_code):
    client = boto3.client(
        'translate',
        region_name=os.environ.get('AWS_REGION'),
        aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY')
    )

    try:
        response = client.translate_text(
            Text=text,
            SourceLanguageCode='en',
            TargetLanguageCode=target_language_code
        )
        return response['TranslatedText']
    except Exception as e:
        return {"error": str(e)}

import os
import boto3

def profile_moderation(text):
    client = boto3.client(
        'comprehend',
        region_name=os.environ.get('AWS_REGION'),
        aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY')
    )

    try:
        # Detects entities for general moderation
        # For more specific moderation, custom classifiers or other services might be needed.
        response = client.detect_sentiment(
            Text=text,
            LanguageCode='en'
        )
        sentiment = response['Sentiment']
        sentiment_score = response['SentimentScore']

        # Simple example: if sentiment is 'NEGATIVE' or 'MIXED' it might need moderation
        if sentiment == 'NEGATIVE' or sentiment == 'MIXED':
            return {"moderation_status": "FLAGGED", "sentiment": sentiment, "score": sentiment_score}
        else:
            return {"moderation_status": "CLEAN", "sentiment": sentiment, "score": sentiment_score}
    except Exception as e:
        return {"error": str(e)}

import os
import boto3

def onboarding_summary(text):
    client = boto3.client(
        'comprehend',
        region_name=os.environ.get('AWS_REGION'),
        aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY')
    )

    try:
        key_phrases_response = client.detect_key_phrases(
            Text=text,
            LanguageCode='en'
        )
        entities_response = client.detect_entities(
            Text=text,
            LanguageCode='en'
        )

        key_phrases = [phrase['Text'] for phrase in key_phrases_response['KeyPhrases']]
        entities = [{'Text': entity['Text'], 'Type': entity['Type']} for entity in entities_response['Entities']]

        return {"key_phrases": key_phrases, "entities": entities}
    except Exception as e:
        return {"error": str(e)}

import os
import boto3
from botocore.exceptions import ClientError

def profile_note_store(user_id, note_id, content, metadata):
    dynamodb = boto3.resource(
        'dynamodb',
        region_name=os.environ.get('AWS_REGION'),
        aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY')
    )

    table_name = os.environ.get('DYNAMODB_NOTES_TABLE_NAME')
    table = dynamodb.Table(table_name)

    try:
        response = table.put_item(
            Item={
                'UserId': user_id,
                'NoteId': note_id,
                'Content': content,
                'Metadata': metadata
            }
        )
        return {"status": "success", "response": response}
    except ClientError as e:
        return {"status": "error", "message": e.response['Error']['Message']}
    except Exception as e:
        return {"status": "error", "message": str(e)}
